1	/**
2	 * The `claim-office` command: MHPCO's counter clerk.
3	 *
4	 * This module is an adapter and owns no underwriting rule. It reads a scenario
5	 * from stdin, puts each step to the office in turn, and writes the office's
6	 * answers to stdout. A step the office refuses ends the whole scenario: the
7	 * clerk writes the reason to stderr and reports failure, leaving stdout empty.
8	 */
9	
10	import { readFileSync } from "node:fs";
11	import {
12	  claim,
13	  createPolicy,
14	  type Customer,
15	  type Incident,
16	  type Item,
17	  type Policy,
18	} from "./claim-office.js";
19	import { afterWritingAContract } from "./customer-standing.js";
20	
21	interface QuoteStep {
22	  readonly op: "quote";
23	  readonly items: readonly Item[];
24	}
25	
26	interface ClaimStep {
27	  readonly op: "claim";
28	  readonly policy: number;
29	  readonly incident: Incident;
30	}
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	interface Scenario {
35	  readonly customer: { readonly yearsWithMHPCO: number };
36	  readonly steps: readonly Step[];
37	}
38	
39	type StepResult = { readonly premium: number } | { readonly payout: number; readonly remainingCap: number };
40	
41	/** The scenario as the office sees it: the customer, and the policies written so far. */
42	interface Counter {
43	  customer: Customer;
44	  readonly policies: Map<number, Policy>;
45	}
46	
47	function handleQuote(counter: Counter, step: QuoteStep, stepIndex: number): StepResult {
48	  const policy = createPolicy(counter.customer, step.items);
49	  counter.policies.set(stepIndex, policy);
50	  counter.customer = afterWritingAContract(counter.customer);
51	  return { premium: policy.premium };
52	}
53	
54	function handleClaim(counter: Counter, step: ClaimStep): StepResult {
55	  const policy = counter.policies.get(step.policy);
56	  if (policy === undefined) {
57	    throw new Error(`step ${step.policy} did not create a policy`);
58	  }
59	  const settlement = claim(policy, step.incident);
60	  counter.policies.set(step.policy, settlement.policy);
61	  return { payout: settlement.payout, remainingCap: settlement.policy.remainingCap };
62	}
63	
64	function runScenario(scenario: Scenario): readonly StepResult[] {
65	  const counter: Counter = {
66	    customer: { yearsWithMHPCO: scenario.customer.yearsWithMHPCO, previousContracts: 0 },
67	    policies: new Map<number, Policy>(),
68	  };
69	  return scenario.steps.map((step, stepIndex) =>
70	    step.op === "quote" ? handleQuote(counter, step, stepIndex) : handleClaim(counter, step),
71	  );
72	}
