1	import { policyBasePremium, policyInsuranceSum } from "./price-list.js";
2	import { type Item } from "./item.js";
3	import { itemRiskSurcharges } from "./item-risk.js";
4	import { policyModifiers } from "./customer-standing.js";
5	import { type Customer } from "./customer.js";
6	import { roundPayoutInMHPCOFavour, roundPremiumInMHPCOFavour } from "./mhpco-rounding.js";
7	import { capPayout, incidentReimbursement, payoutCap, type Incident } from "./claims.js";
8	import { coverageOf } from "./policy-coverage.js";
9	
10	export type { Item, Customer };
11	export type { Incident, Damage } from "./claims.js";
12	
13	/** A policy MHPCO has written: what it covers and what it was quoted for. */
14	export interface Policy {
15	  readonly premium: number;
16	  readonly insuranceSum: number;
17	  readonly items: readonly Item[];
18	  /** What the office may still pay out on this policy. */
19	  readonly remainingCap: number;
20	}
21	
22	/**
23	 * The settlement of one claim: what MHPCO pays, and the policy as it stands
24	 * afterwards — a claim consumes part of the cap, so later claims against the
25	 * same policy are settled against what is left, and `policy.remainingCap` is
26	 * the one record of what the office may still pay out.
27	 */
28	export interface Settlement {
29	  readonly payout: number;
30	  readonly policy: Policy;
31	}
32	
33	/**
34	 * Writes a policy for the items the customer wishes to insure: the premium they
35	 * owe, and the insurance sum the office's payouts are measured against.
36	 */
37	export function createPolicy(customer: Customer, items: readonly Item[]): Policy {
38	  const insuranceSum = policyInsuranceSum(items);
39	  return {
40	    premium: quote(customer, items),
41	    insuranceSum,
42	    items,
43	    remainingCap: payoutCap(insuranceSum),
44	  };
45	}
46	
47	/**
48	 * Settles a damage report against a policy MHPCO has written, in the order the
49	 * office settles it: what the report's damages come to under the reimbursement
50	 * clauses, held down to what the policy's cap still allows, and rounded once at
51	 * the end — the amount that actually leaves the office is the final payout, so
52	 * the office's favour is taken on that and not on the uncapped total.
53	 *
54	 * Each of those rulings is made elsewhere; this function only knows their order.
55	 */
56	export function claim(policy: Policy, incident: Incident): Settlement {
57	  const owed = incidentReimbursement(incident, coverageOf(policy.items));
58	  const capped = capPayout(owed, policy.remainingCap);
59	  return {
60	    payout: roundPayoutInMHPCOFavour(capped.payout),
61	    policy: { ...policy, remainingCap: capped.remainingCap },
62	  };
63	}
64	
65	/** MHPCO adds a flat processing fee to every premium, at the very end. */
66	const PROCESSING_FEE_G = 5;
67	
68	/**
69	 * Assembles the bill in the order the office bills it: the price-list base
70	 * premium of the policy, the risk surcharges its individual items carry, the
71	 * modifiers rated on the policy as a whole, and finally the processing fee.
72	 *
73	 * Each of those amounts is ruled on elsewhere; this function only knows the
74	 * order they are applied in and that the total is rounded once, at the end.
75	 */
76	export function quote(customer: Customer, items: readonly Item[]): number {
77	  const policyBase = policyBasePremium(items);
78	  const premium =
79	    policyBase +
80	    itemRiskSurcharges(items) +
81	    policyModifiers(customer, policyBase) +
82	    PROCESSING_FEE_G;
83	  return roundPremiumInMHPCOFavour(premium);
84	}
